import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.C0KMm31j.js";const c="/Nav2ArticlesSite/article-assets/2026-07-23/nav2_dwb_core_01_cycle.png",r="/Nav2ArticlesSite/article-assets/2026-07-23/nav2_dwb_core_02_dynamic_window.png",l="/Nav2ArticlesSite/article-assets/2026-07-23/nav2_dwb_core_03_rollout.png",d="/Nav2ArticlesSite/article-assets/2026-07-23/nav2_dwb_core_04_mapgrid.png",n="/Nav2ArticlesSite/article-assets/2026-07-23/nav2_dwb_core_05_critics.png",s="/Nav2ArticlesSite/article-assets/2026-07-23/nav2_dwb_core_06_selection.png",q=JSON.parse('{"title":"每 50 毫秒淘汰数百种走法：DWB 如何从速度窗口里选出机器人下一步？","description":"DWB 不直接把路径变成一个固定转角。它在每个控制周期里生成一批可达速度，向前推演对应轨迹，再用多组 Critic 衡量碰撞、贴近路径、趋近目标和动作合理性。违法轨迹被淘汰，合法轨迹中总分最低者成为本周期速度。","frontmatter":{"title":"每 50 毫秒淘汰数百种走法：DWB 如何从速度窗口里选出机器人下一步？","description":"DWB 不直接把路径变成一个固定转角。它在每个控制周期里生成一批可达速度，向前推演对应轨迹，再用多组 Critic 衡量碰撞、贴近路径、趋近目标和动作合理性。违法轨迹被淘汰，合法轨迹中总分最低者成为本周期速度。","date":"2026-07-23","section":"三 · 局部控制与速度生成","readingTime":6,"source":"2026-07-23/nav2_dwb_core_algorithm.md","status":"published","cover":"/article-assets/2026-07-23/nav2_dwb_core_01_cycle.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-dwb-core-algorithm"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"每 50 毫秒淘汰数百种走法：DWB 如何从速度窗口里选出机器人下一步？"}],["meta",{"property":"og:description","content":"DWB 不直接把路径变成一个固定转角。它在每个控制周期里生成一批可达速度，向前推演对应轨迹，再用多组 Critic 衡量碰撞、贴近路径、趋近目标和动作合理性。违法轨迹被淘汰，合法轨迹中总分最低者成为本周期速度。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-dwb-core-algorithm"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-23/nav2_dwb_core_01_cycle.png"}],["meta",{"property":"article:published_time","content":"2026-07-23"}],["meta",{"name":"twitter:title","content":"每 50 毫秒淘汰数百种走法：DWB 如何从速度窗口里选出机器人下一步？"}],["meta",{"name":"twitter:description","content":"DWB 不直接把路径变成一个固定转角。它在每个控制周期里生成一批可达速度，向前推演对应轨迹，再用多组 Critic 衡量碰撞、贴近路径、趋近目标和动作合理性。违法轨迹被淘汰，合法轨迹中总分最低者成为本周期速度。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-23/nav2_dwb_core_01_cycle.png"}]],"prev":{"text":"机器人明明在动，Nav2 为什么还要追问速度？拆解 Odometry 如何驱动控制闭环","link":"/nav2/nav2-controller-odometry-velocity-flow"},"next":{"text":"一条 Path，如何被 53 个函数炼成速度？逐函数拆解 Nav2 Controller Server","link":"/nav2/nav2-controller-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-dwb-core-algorithm.md","filePath":"nav2/nav2-dwb-core-algorithm.md","lastUpdated":null}'),h={name:"nav2/nav2-dwb-core-algorithm.md"};function p(_,e,m,b,u,v){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="每-50-毫秒淘汰数百种走法-dwb-如何从速度窗口里选出机器人下一步" tabindex="-1">每 50 毫秒淘汰数百种走法：DWB 如何从速度窗口里选出机器人下一步？ <a class="header-anchor" href="#每-50-毫秒淘汰数百种走法-dwb-如何从速度窗口里选出机器人下一步" aria-label="Permalink to &quot;每 50 毫秒淘汰数百种走法：DWB 如何从速度窗口里选出机器人下一步？&quot;">​</a></h1><p>DWB 不直接把路径变成一个固定转角。它在每个控制周期里生成一批可达速度，向前推演对应轨迹，再用多组 Critic 衡量碰撞、贴近路径、趋近目标和动作合理性。违法轨迹被淘汰，合法轨迹中总分最低者成为本周期速度。</p><h2 id="一、dwb-的核心是离散局部优化" tabindex="-1">一、DWB 的核心是离散局部优化 <a class="header-anchor" href="#一、dwb-的核心是离散局部优化" aria-label="Permalink to &quot;一、DWB 的核心是离散局部优化&quot;">​</a></h2><h3 id="_1-1-输入不是只有路径" tabindex="-1">1.1 输入不是只有路径 <a class="header-anchor" href="#_1-1-输入不是只有路径" aria-label="Permalink to &quot;1.1 输入不是只有路径&quot;">​</a></h3><p>一次计算需要当前位姿、当前速度、局部化后的 Path、Local Costmap、机器人运动学限制和目标姿态。DWB 求解的是一个有限集合上的最小化问题：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v* = argmin J(trajectory(v))</span></span></code></pre></div><p>候选速度 <code>v=(vx, vy, vθ)</code> 先生成未来轨迹，再计算代价 <code>J</code>。算法只执行最优轨迹携带的速度，不执行整条模拟轨迹。</p><h3 id="_1-2-单周期闭环" tabindex="-1">1.2 单周期闭环 <a class="header-anchor" href="#_1-2-单周期闭环" aria-label="Permalink to &quot;1.2 单周期闭环&quot;">​</a></h3><p><img src="'+c+`" alt="DWB 单控制周期核心算法"></p><p>当前项目的 Controller 频率为 <code>20 Hz</code>，约每 <code>50 ms</code> 重算一次。上个周期的最优解并不会锁死未来；新的 Odom、Costmap 和 Path 会立即改变下一轮候选及评分。</p><h2 id="二、动态窗口决定-哪些速度有资格参赛" tabindex="-1">二、动态窗口决定“哪些速度有资格参赛” <a class="header-anchor" href="#二、动态窗口决定-哪些速度有资格参赛" aria-label="Permalink to &quot;二、动态窗口决定“哪些速度有资格参赛”&quot;">​</a></h2><h3 id="_2-1-可达范围来自两类边界" tabindex="-1">2.1 可达范围来自两类边界 <a class="header-anchor" href="#_2-1-可达范围来自两类边界" aria-label="Permalink to &quot;2.1 可达范围来自两类边界&quot;">​</a></h3><p>每个速度轴都先受全局上下限约束，再受当前速度和加减速度约束。单轴可达范围可概括为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_low  = max(v_min, v0 + decel × Δt)</span></span>
<span class="line"><span>v_high = min(v_max, v0 + accel × Δt)</span></span></code></pre></div><p><code>decel</code> 在配置中通常为负值。<code>StandardTrajectoryGenerator</code> 用 <code>sim_time</code> 构造范围；<code>LimitedAccelGenerator</code> 用一个控制周期 <code>sim_period</code> 构造更窄的经典 Dynamic Window。</p><h3 id="_2-2-离散采样形成候选集合" tabindex="-1">2.2 离散采样形成候选集合 <a class="header-anchor" href="#_2-2-离散采样形成候选集合" aria-label="Permalink to &quot;2.2 离散采样形成候选集合&quot;">​</a></h3><p><img src="`+r+'" alt="DWB 动态窗口与速度采样"></p><p><code>vx</code>、<code>vy</code>、<code>vtheta</code> 分别均匀采样后做笛卡尔积。跨越零点时迭代器会保留零速度，再过滤超出合速度限制和全零的组合。</p><p>当前差速配置为 <code>vx_samples=20</code>、<code>vtheta_samples=20</code>、<code>vy=0</code>，候选规模接近数百条，但实际数量会受零点补样和有效速度过滤影响，不能简单认定永远等于某个固定值。</p><h2 id="三、一组速度如何长成未来轨迹" tabindex="-1">三、一组速度如何长成未来轨迹 <a class="header-anchor" href="#三、一组速度如何长成未来轨迹" aria-label="Permalink to &quot;三、一组速度如何长成未来轨迹&quot;">​</a></h2><h3 id="_3-1-速度先受加速度限制" tabindex="-1">3.1 速度先受加速度限制 <a class="header-anchor" href="#_3-1-速度先受加速度限制" aria-label="Permalink to &quot;3.1 速度先受加速度限制&quot;">​</a></h3><p>采样值是目标速度，不代表机器人能瞬间达到。<code>computeNewVelocity()</code> 在每个离散步内让当前速度向目标逼近，且不越过加速度或减速度允许的变化量。</p><h3 id="_3-2-位姿按机器人坐标系积分" tabindex="-1">3.2 位姿按机器人坐标系积分 <a class="header-anchor" href="#_3-2-位姿按机器人坐标系积分" aria-label="Permalink to &quot;3.2 位姿按机器人坐标系积分&quot;">​</a></h3><p><img src="'+l+'" alt="DWB 候选轨迹离散积分"></p><p>更新后的 <code>vx</code>、<code>vy</code> 会结合当前航向转换到地图坐标，<code>vtheta</code> 更新朝向。离散步数由时间粒度决定，或由预测线位移、角位移与对应粒度共同决定。最终得到包含候选速度、Pose 序列和时间偏移的 <code>Trajectory2D</code>。</p><p><code>sim_time</code> 越长，算法看得越远，但弯道切角和计算量也可能增加；粒度越细，碰撞与几何评分更密，计算成本也更高。</p><h2 id="四、mapgrid-把路径关系变成查表" tabindex="-1">四、MapGrid 把路径关系变成查表 <a class="header-anchor" href="#四、mapgrid-把路径关系变成查表" aria-label="Permalink to &quot;四、MapGrid 把路径关系变成查表&quot;">​</a></h2><h3 id="_4-1-路径与目标分别成为零代价源" tabindex="-1">4.1 路径与目标分别成为零代价源 <a class="header-anchor" href="#_4-1-路径与目标分别成为零代价源" aria-label="Permalink to &quot;4.1 路径与目标分别成为零代价源&quot;">​</a></h3><p><img src="'+d+'" alt="DWB Path 与 Goal 的 MapGrid 距离场"></p><p><code>PathDist</code> 将局部路径覆盖的有效栅格设为零，<code>GoalDist</code> 将局部 Costmap 内最后一个路径点设为零。队列从这些源点向外传播曼哈顿距离，形成可复用的栅格距离场。</p><h3 id="_4-2-轨迹评分变成栅格查询" tabindex="-1">4.2 轨迹评分变成栅格查询 <a class="header-anchor" href="#_4-2-轨迹评分变成栅格查询" aria-label="Permalink to &quot;4.2 轨迹评分变成栅格查询&quot;">​</a></h3><p>候选轨迹的 Pose 映射到栅格后，可以按 <code>last</code>、<code>sum</code> 或 <code>product</code> 聚合距离。<code>PathAlign</code> 和 <code>GoalAlign</code> 还会查询机器人前方点，使朝向对齐不只依赖轨迹终点。</p><p>这种做法把大量“点到路径”的几何计算转换成预处理加查表，适合在一个周期内批量评估数百条轨迹。</p><h2 id="五、critic-如何表达驾驶偏好" tabindex="-1">五、Critic 如何表达驾驶偏好 <a class="header-anchor" href="#五、critic-如何表达驾驶偏好" aria-label="Permalink to &quot;五、Critic 如何表达驾驶偏好&quot;">​</a></h2><h3 id="_5-1-安全项拥有否决权" tabindex="-1">5.1 安全项拥有否决权 <a class="header-anchor" href="#_5-1-安全项拥有否决权" aria-label="Permalink to &quot;5.1 安全项拥有否决权&quot;">​</a></h3><p><img src="'+n+'" alt="DWB 核心 Critic 职责"></p><p><code>BaseObstacle</code> 或 <code>ObstacleFootprint</code> 发现碰撞、越界或不可达区域时，可以抛出违法轨迹异常。<code>RotateToGoal</code> 也会拒绝终点窗口内不减速或仍带平移速度的轨迹。这些不是“扣几分”，而是直接取消候选资格。</p><h3 id="_5-2-引导项塑造剩余轨迹" tabindex="-1">5.2 引导项塑造剩余轨迹 <a class="header-anchor" href="#_5-2-引导项塑造剩余轨迹" aria-label="Permalink to &quot;5.2 引导项塑造剩余轨迹&quot;">​</a></h3><ul><li><code>PathDist</code>、<code>PathAlign</code>：靠近并对齐局部路径。</li><li><code>GoalDist</code>、<code>GoalAlign</code>：向局部目标推进并调整朝向。</li><li><code>Oscillation</code>：抑制反复换向。</li><li><code>PreferForward</code>、<code>Twirling</code>：表达前进和少旋转偏好。</li></ul><p>项目当前启用其中七项：<code>RotateToGoal</code>、<code>Oscillation</code>、<code>BaseObstacle</code>、<code>GoalAlign</code>、<code>PathAlign</code>、<code>PathDist</code>、<code>GoalDist</code>。</p><h2 id="六、最低总分如何胜出" tabindex="-1">六、最低总分如何胜出 <a class="header-anchor" href="#六、最低总分如何胜出" aria-label="Permalink to &quot;六、最低总分如何胜出&quot;">​</a></h2><h3 id="_6-1-加权和不是简单投票" tabindex="-1">6.1 加权和不是简单投票 <a class="header-anchor" href="#_6-1-加权和不是简单投票" aria-label="Permalink to &quot;6.1 加权和不是简单投票&quot;">​</a></h3><p>合法轨迹的总分为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>J = Σ(raw_score_i × scale_i)</span></span></code></pre></div><p><img src="'+s+'" alt="DWB 非法淘汰、加权短路与最优选择"></p><p>Critic 按配置顺序运行。启用 <code>short_circuit_trajectory_evaluation</code> 后，累计分一旦超过当前最优总分，后续项可以停止计算，因为分数继续累加只会更差。</p><h3 id="_6-2-scale-大不等于一定主导" tabindex="-1">6.2 Scale 大不等于一定主导 <a class="header-anchor" href="#_6-2-scale-大不等于一定主导" aria-label="Permalink to &quot;6.2 Scale 大不等于一定主导&quot;">​</a></h3><p>不同 Critic 的原始分数量纲不同，不能只看 <code>scale</code> 大小判断谁最重要。调参时应同时观察原始分、加权分和淘汰原因；否则把 <code>PathDist.scale</code> 翻倍，实际效果可能远小于一次障碍碰撞否决。</p><p>全部候选违法时，DWB 不会勉强输出“最不坏”的轨迹，而是报告无合法轨迹。这通常指向 Footprint、局部 Costmap、速度窗口或终点动作约束问题。</p><h2 id="七、核心参数应该按哪条链调整" tabindex="-1">七、核心参数应该按哪条链调整 <a class="header-anchor" href="#七、核心参数应该按哪条链调整" aria-label="Permalink to &quot;七、核心参数应该按哪条链调整&quot;">​</a></h2><h3 id="_7-1-候选不足" tabindex="-1">7.1 候选不足 <a class="header-anchor" href="#_7-1-候选不足" aria-label="Permalink to &quot;7.1 候选不足&quot;">​</a></h3><p>检查速度上下限、<code>vx_samples</code>、<code>vtheta_samples</code>、加减速度和生成器类型。采样过少会漏掉窄通道可行解，过多则提高每周期计算量。</p><h3 id="_7-2-轨迹预测不合适" tabindex="-1">7.2 轨迹预测不合适 <a class="header-anchor" href="#_7-2-轨迹预测不合适" aria-label="Permalink to &quot;7.2 轨迹预测不合适&quot;">​</a></h3><p>检查 <code>sim_time</code>、<code>linear_granularity</code> 和 <code>angular_granularity</code>。预测太短容易目光短浅，太长可能让局部轨迹过度受远处几何影响。</p><h3 id="_7-3-行为偏好不合理" tabindex="-1">7.3 行为偏好不合理 <a class="header-anchor" href="#_7-3-行为偏好不合理" aria-label="Permalink to &quot;7.3 行为偏好不合理&quot;">​</a></h3><p>先区分违法淘汰与合法高分，再调整 Critic。贴障碍先核对 Footprint 和障碍项，偏离路径再看 Path／Goal 距离场，终点抖动再看 <code>RotateToGoal</code> 与 <code>Oscillation</code>。</p><h2 id="八、把-dwb-记成一句话" tabindex="-1">八、把 DWB 记成一句话 <a class="header-anchor" href="#八、把-dwb-记成一句话" aria-label="Permalink to &quot;八、把 DWB 记成一句话&quot;">​</a></h2><p>DWB 是“可达速度离散采样＋有限时域轨迹推演＋多 Critic 代价选择”。它不是求连续最优控制，也不是机械追踪最近路径点；它用当前局部地图和运动学条件，在每个控制周期重新挑选一条可执行、代价最低的短期未来。</p><p><a href="https://docs.nav2.org/configuration/packages/configuring-dwb-controller.html" target="_blank" rel="noreferrer">Nav2 DWB Controller 配置说明</a></p><p><a href="https://github.com/ros-navigation/navigation2/tree/main/nav2_dwb_controller" target="_blank" rel="noreferrer">Nav2 DWB Controller 上游源码</a></p>',60)])])}const x=a(h,[["render",p]]);export{q as __pageData,x as default};
